exec python3 -c 'exec("import sys,json\nA=\"<>+-.,[]\"\ndef N(n):\n s=\"\"\n while n:n,r=divmod(n-1,8);s=A[r]+s\n return s\ndef G(b):\n n=1\n for x in b:n=n*257+x+1\n return n\ndef D(n):\n b=[]\n while n>1:n,r=divmod(n,257);b.append(r-1)\n return bytes(b[::-1])\ndef M(s):\n n=0\n for c in s:n=8*n+A.index(c)+1\n return n\ndef C(x):\n if isinstance(x,str):return [\"a\",x]\n return [\"s\",sorted((C(z) for z in x),key=str)]\ndef U(n,d):\n return (n+1,1) if d==0 else ((n-1,0) if n else (0,1))\ndepth=int(sys.argv[2]) if len(sys.argv)>2 else 2\nassert 0<=depth<=2,\"Full expansion is limited to 2 levels\"\nraw=open(sys.argv[1],\"rb\").read();e=N(G(raw));X=frozenset([e]);out=[]\nfor i in range(depth):\n f=tuple(frozenset([N(2*i+1),N(2*i+2)])-X)\n S={X|frozenset(f[j] for j in range(len(f)) if mask>>j&1) for mask in range(1<<len(f))}\n desc=json.dumps([e,i,\"Sup2\"],separators=(\",\",\":\")).encode();code=N(G(desc));assert D(M(code))==desc\n F=frozenset(S);Y=X|F|frozenset([F,code]);assert X<Y and X in Y and F in Y and len(S)==4;X=Y\n out.append([i+1,len(X),len(S)])\nprint(json.dumps({\"bytes\":len(raw),\"symbols\":len(e),\"roundtrip\":D(M(e))==raw,\"U2\":all(U(*U(i,d))==(i,d) for i in range(4) for d in (0,1)),\"layers\":out}))\n")' "$0" "$@"
